void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 fragColor;
vec2 fragCoord;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
uv = uv*(0.9-0.4*sin(uTime*0.2));
#ifdef bass_smooth
uv *= (int)vis_version > 2 ? 1.0 * vis_intensity+vis_shift : (1.0 - (smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth)*0.25))*vis_intensity+vis_shift;
#else
uv *= (1.0 - (smoothstep( 0.0 , 2.0 ,audioLowSmooth)*0.05));
#endif
// vec2 uv = (fragCoord-(uTexSize.xy/2.))/uTexSize.x;
vec3 ro = vec3(0.,0.,-50.);
ro.xz = rotate(ro.xz,uTime);
vec3 cf = normalize(-ro);
vec3 cs = normalize(cross(cf,vec3(0.,1.,0.)));
vec3 cu = normalize(cross(cf,cs));
vec3 uuv = ro+cf*3. + uv.x*cs + uv.y*cu;
vec3 rd = normalize(uuv-ro);
vec4 col = rm(ro,rd);
ret = col;
  fragColor = vec4(ret, 1.0);
}

